document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("lottery-form"),n=document.getElementById("lottery-result"),t=e["has-bonus"],i=document.getElementById("bonus-section"),o=document.getElementById("bonus-total-section");t.addEventListener("change",function(){this.checked?(i.style.display="block",o.style.display="block"):(i.style.display="none",o.style.display="none")}),e.addEventListener("submit",function(t){t.preventDefault();const i=e["lottery-name"].value.trim()||"This Lottery",o=parseInt(e["main-pick"].value),r=parseInt(e["main-total"].value),d=e["has-bonus"].checked,a=parseInt(e["bonus-pick"].value)||1,s=parseInt(e["bonus-total"].value)||1,l=parseFloat(e["ticket-cost"].value)||0;if(!o||!r||o>r)return n.innerHTML='<p style="color:red;">Please enter valid main number values. Numbers to pick must be less than or equal to total numbers.</p>',void 0;if(d&&a>s)return n.innerHTML='<p style="color:red;">Bonus numbers to pick must be less than or equal to total bonus numbers.</p>',void 0;const p=function(e,n){if(n>e)return 0;if(0===n||n===e)return 1;n=Math.min(n,e-n);let t=1;for(let i=0;i<n;i++)t=t*(e-i)/(i+1);return Math.round(t)}(r,o),c=d?p*s:p,g=1/c*100,m=e=>e<1e3?e.toString():e<1e6?(e/1e3).toFixed(1)+"K":e<1e9?(e/1e6).toFixed(1)+"M":(e/1e9).toFixed(1)+"B",u=e=>e.toLocaleString("en-US");let y="";if(l>0){const e=50*l*1e6/c-l,n=(e+l)/l*100;y=`\n        <div style="background: linear-gradient(135deg, #ffebee 0%, #ffcdd2 100%); padding: 15px; border-radius: 10px; margin: 15px 0; border: 2px solid #f44336;">\n          <h4 style="color: #c62828; margin-top: 0;">💸 Expected Value Analysis</h4>\n          <p><strong>Ticket Cost:</strong> $${l.toFixed(2)}</p>\n          <p><strong>Expected Return:</strong> $${(e+l).toFixed(6)} per ticket</p>\n          <p><strong>Expected Loss:</strong> $${(-e).toFixed(2)} per ticket (${(100-n).toFixed(1)}%)</p>\n          <p style="font-style: italic; color: #666; margin: 10px 0 0 0;">\n            Note: This assumes average jackpot sizes. Actual expected value varies with current jackpot.\n          </p>\n        </div>\n      `}const v=(x=c,[{event:"Being struck by lightning in a lifetime",odds:15300,emoji:"⚡"},{event:"Dying in a car accident this year",odds:8096,emoji:"🚗"},{event:"Dying in a plane crash",odds:11e6,emoji:"✈️"},{event:"Becoming a professional athlete",odds:22e3,emoji:"🏆"},{event:"Dating a millionaire",odds:215,emoji:"💰"},{event:"Finding a four-leaf clover",odds:1e4,emoji:"🍀"},{event:"Getting a hole-in-one (amateur)",odds:12500,emoji:"⛳"},{event:"Being dealt a royal flush in poker",odds:649740,emoji:"🃏"},{event:"Getting struck by lightning this year",odds:1e6,emoji:"⚡"},{event:"Becoming a movie star",odds:15e5,emoji:"🎬"}].filter(e=>e.odds<x).sort((e,n)=>n.odds-e.odds).slice(0,5).map(e=>({...e,multiplier:(x/e.odds).toFixed(0)})));var x;n.innerHTML=`\n      <div style="background: linear-gradient(135deg, #e3f2fd 0%, #bbdefb 100%); padding: 25px; border-radius: 15px; margin: 20px 0; border: 2px solid #2196f3;">\n        <h3 style="color: #1565c0; margin-top: 0; text-align: center;">🎲 ${i} Probability Results</h3>\n        \n        <div style="background: white; padding: 15px; border-radius: 10px; margin: 15px 0; text-align: center;">\n          <p style="margin: 5px 0; color: #666;">\n            <strong>Format:</strong> Pick ${o} from ${r}${d?` + ${a} from ${s}`:""}\n          </p>\n        </div>\n\n        <div class="insight-cards">\n          <div class="insight-card info">\n            <h6>🎯 Your Odds</h6>\n            <div class="big-number">1 in ${m(c)}</div>\n            <p>Exactly: 1 in ${u(c)}</p>\n          </div>\n          \n          <div class="insight-card warning">\n            <h6>📊 Probability</h6>\n            <div class="big-number">${g<.001?g.toExponential(2):g.toFixed(6)}%</div>\n            <p>Chance of winning on one ticket</p>\n          </div>\n          \n          <div class="insight-card" style="border-color: #ff5722; background: linear-gradient(135deg, #fff3e0 0%, #ffe0d1 100%);">\n            <h6>🔢 Total Combinations</h6>\n            <div class="big-number" style="color: #ff5722;">${m(c)}</div>\n            <p>Possible number combinations</p>\n          </div>\n        </div>\n\n        ${y}\n\n        <div style="background: linear-gradient(135deg, #f3e5f5 0%, #e1bee7 100%); padding: 20px; border-radius: 10px; margin: 20px 0; border: 2px solid #9c27b0;">\n          <h4 style="color: #6a1b9a; margin-top: 0; text-align: center;">⏰ Time Perspective</h4>\n          \n          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 15px;">\n            <div style="background: white; padding: 15px; border-radius: 8px; text-align: center;">\n              <h6 style="color: #6a1b9a; margin: 0 0 10px 0;">Playing Weekly</h6>\n              <div style="font-size: 1.4rem; font-weight: bold; color: #333;">\n                ${m(Math.round(c/52))} years\n              </div>\n              <p style="margin: 5px 0 0 0; font-size: 0.85rem; color: #666;">Expected wait time</p>\n            </div>\n            \n            <div style="background: white; padding: 15px; border-radius: 8px; text-align: center;">\n              <h6 style="color: #6a1b9a; margin: 0 0 10px 0;">Playing Daily</h6>\n              <div style="font-size: 1.4rem; font-weight: bold; color: #333;">\n                ${m(Math.round(c/365))} years\n              </div>\n              <p style="margin: 5px 0 0 0; font-size: 0.85rem; color: #666;">Expected wait time</p>\n            </div>\n          </div>\n        </div>\n\n        ${v.length>0?`\n        <div style="background: linear-gradient(135deg, #e8f5e8 0%, #c8e6c9 100%); padding: 20px; border-radius: 10px; margin: 20px 0; border: 2px solid #4caf50;">\n          <h4 style="color: #2e7d32; margin-top: 0; text-align: center;">📈 You're More Likely To...</h4>\n          <div style="display: grid; gap: 10px;">\n            ${v.map(e=>`\n              <div style="background: white; padding: 12px; border-radius: 6px; display: flex; align-items: center; gap: 10px;">\n                <span style="font-size: 1.5rem;">${e.emoji}</span>\n                <div style="flex: 1;">\n                  <strong>${e.event}</strong><br>\n                  <span style="color: #666; font-size: 0.9rem;">${e.multiplier}× more likely (1 in ${u(e.odds)})</span>\n                </div>\n              </div>\n            `).join("")}\n          </div>\n        </div>\n        `:""}\n\n        <div style="background: linear-gradient(135deg, #fff8e1 0%, #fff3c4 100%); padding: 20px; border-radius: 10px; margin: 20px 0; border: 2px solid #ffa726;">\n          <h4 style="color: #e65100; margin-top: 0; text-align: center;">💡 Reality Check</h4>\n          \n          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px;">\n            <div style="background: white; padding: 15px; border-radius: 8px;">\n              <h6 style="color: #e65100; margin-top: 0;">🎟️ If you bought 100 tickets:</h6>\n              <p style="margin: 5px 0; font-size: 1.1rem;"><strong>Odds:</strong> 100 in ${u(c)}</p>\n              <p style="margin: 5px 0; color: #666;">Still a ${g<.1?(100*g).toExponential(2):(100*g).toFixed(4)}% chance</p>\n            </div>\n            \n            <div style="background: white; padding: 15px; border-radius: 8px;">\n              <h6 style="color: #e65100; margin-top: 0;">🔢 Mathematical Truth:</h6>\n              <p style="margin: 5px 0;">Every combination has <strong>exactly the same odds</strong></p>\n              <p style="margin: 5px 0; color: #666;">1-2-3-4-5 = random quick pick</p>\n            </div>\n          </div>\n        </div>\n\n        <div style="text-align: center; margin-top: 20px; padding: 15px; background: rgba(255,255,255,0.9); border-radius: 8px;">\n          <p style="margin: 0; font-style: italic; color: #666;">\n            🎲 <strong>Remember:</strong> The lottery is entertainment, not an investment. Play responsibly and never spend money you can't afford to lose!\n          </p>\n        </div>\n      </div>\n    `})});